// agentpager-claude v2
// AgentPager (Claude Code) bridge hook runner
// Managed by AgentPager (Claude Code) - do not edit this file manually.
// Forwards Claude Code lifecycle hooks to AgentPager Bridge on 127.0.0.1:49361.

const net = require("node:net");

const HOST = "127.0.0.1";
const PORT = 49361;
const CONNECT_TIMEOUT_MS = 500;

// 只有权限事件需要把 Bridge 的答复写回 stdout；其余事件必须保持 stdout 全空。
// 依据：Claude Code 把 exit 0 的非 JSON stdout 当作纯文本注入上下文，而纯文本只在
// UserPromptSubmit / UserPromptExpansion / SessionStart / PostModelSwitch 上生效。
// 旧实现（bridge exe --hook）在每条事件回写一个裸换行，等于每次提交提示词都往上下文塞空行。
const PERMISSION_EVENT = "PermissionRequest";

// 转发前的兜底： stdin 迟迟不结束（Claude Code 异常）时不要挂死调用方。
// 转发一旦开始，退出交给 socket 事件闭环（宁慢不丢）。
let forwarding = false;
const safetyTimer = setTimeout(() => {
  if (!forwarding) process.exit(0);
}, 5000);
if (safetyTimer.unref) safetyTimer.unref();

let input = "";
process.stdin.setEncoding("utf8");

process.stdin.on("data", chunk => {
  input += chunk;
});

process.stdin.on("end", () => {
  let payload = {};
  if (input.trim()) {
    try {
      payload = JSON.parse(input);
    } catch {
      payload = {};
    }
  }
  forward(payload);
});

process.stdin.on("error", () => {
  process.exit(0);
});

function forward(payload) {
  forwarding = true;

  const isPermission = payload && payload.hook_event_name === PERMISSION_EVENT;
  const envelope = { hook_source: "claude", payload };

  const client = net.createConnection({ host: HOST, port: PORT });
  client.setTimeout(CONNECT_TIMEOUT_MS);

  let replied = false;

  client.on("connect", () => {
    // 权限事件需要长等（Bridge 挂住连接直到手机作答或超时），取消连接超时。
    client.setTimeout(isPermission ? 0 : CONNECT_TIMEOUT_MS);
    try {
      client.write(JSON.stringify(envelope) + "\n");
    } catch {
      client.destroy();
      process.exit(0);
    }
  });

  client.on("data", chunk => {
    // 只有权限事件消费回包；其余事件即使收到字节也一律不写 stdout。
    if (!isPermission) return;
    replied = true;
    try {
      process.stdout.write(chunk);
    } catch {
      // 忽略输出异常
    }
    // 回包写完即收工：不依赖对端是否关闭连接（实测 Claude Code 读完 stdout 后不一定关 socket，
    // 只等 close 会白挂一个 node 进程直到 24 小时超时）。优雅关闭（发 FIN，避免 ECONNRESET），
    // 真正的退出交给下面的 close 处理，那里会让进程自然退出，保证管道 stdout 被完整 flush。
    try { client.end(); } catch { /* 忽略 */ }
  });

  client.on("timeout", () => {
    client.destroy();
    process.exit(0);
  });

  client.on("error", () => {
    // Fail-Open：Bridge 未启动时静默退出，绝不阻断 Claude Code。
    // 权限事件不回包 = Claude Code 照常弹出本地对话框，用户在本机作答即可。
    client.destroy();
    process.exit(0);
  });

  client.on("close", () => {
    if (!replied) {
      process.exit(0);
      return;
    }
    // 已把回包写给 Claude：让进程**自然退出**（管道 stdout 是异步的，直接 exit 会截断输出）。
    // 兜底定时器必须 unref——否则它自己就把事件循环钉住，反而变成"每次都等满 1 秒"。
    // unref 之后：没有别的 handle 立刻自然退；有漏网 handle 时才由它兜底收场。
    const fallback = setTimeout(() => process.exit(0), 1000);
    if (fallback.unref) fallback.unref();
  });
}
